// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Hücre, canlıların temel bileşenleri ve hücre bölünmeleri (zor).
const ozBiology1Zor = <(String, String, List<String>, String)>[
  ('Proteinlerin yapısındaki bazı amino asitlerde bulunan ve disülfit köprülerinin oluşmasını sağlayan element hangisidir?', 'Kükürt', ['Fosfor', 'Sodyum', 'Klor'], 'Sistein amino asidindeki kükürt atomları arasında disülfit (S–S) bağları kurulur ve bu bağlar protein yapısını sağlamlaştırır.'),
  ('Bir bitkinin glikozu suda çözünen bir şeker yerine nişasta biçiminde depolaması ona hangi avantajı sağlar?', 'Hücrede osmotik basıncı artırmadan çok miktarda glikoz saklayabilmek', ['Depolanan glikozun hücrede beklemeden hemen enerjiye dönüşmesini sağlamak', 'Hücre duvarını kalınlaştırmak', 'Glikozun hücre dışına sızmasını hızlandırmak'], 'Nişasta büyük ve suda çözünmeyen bir moleküldür; bu yüzden hücrenin su dengesini bozmaz. Aynı miktar serbest glikoz ise hücreye aşırı su çekerdi.'),
  ('Bir dizi şeker çözeltisinden yalnız biri Benedict testinde renk değişimi göstermiyor. Bu çözelti hangisi olabilir?', 'Sükroz', ['Glikoz', 'Fruktoz', 'Maltoz'], 'Benedict testi indirgen şekerleri belirler. Glikoz, fruktoz ve maltoz indirgendir; sükrozda indirgen uçlar bağa katıldığı için test olumsuzdur.'),
  ('Develerin hörgüçlerinde depoladıkları yağ, su bulamadıkları dönemlerde onlara hangi yolla katkı sağlar?', 'Yağın solunumla yıkılması sonucunda metabolik su oluşması', ['Yağın doğrudan kana geçip su gibi davranması', 'Yağın böbreklerde hiçbir değişime uğramadan doğrudan suya dönüşmesi', 'Yağın terle birlikte vücudu serinletmesi'], 'Yağlar oksijenli solunumla yıkıldığında CO₂ ile birlikte bol miktarda su oluşur. Bu metabolik su çöl hayvanları için önemlidir.'),
  ('Yağlı tohumlu bitkilerin tohumlarında enerjiyi nişasta yerine yağ olarak depolamalarının avantajı ne olabilir?', 'Aynı enerjiyi daha az kütle ve hacimle taşıyabilmek', ['Tohumun suyu daha hızlı emmesini ve hemen çimlenmesini sağlamak', 'Fotosentezi tohum içinde başlatmak', 'Tohumda protein sentezini durdurmak'], 'Yağ, gram başına karbonhidrattan yaklaşık iki kat enerji içerdiğinden hafif ve küçük tohumlar için verimli bir depo maddesidir.'),
  ('Margarin üretiminde sıvı bitkisel yağlara hidrojen eklenerek katılaştırılması hangi değişime dayanır?', 'Çift bağların doyurularak tekli bağa dönüştürülmesi', ['Gliserolün yapıdan çıkarılması', 'Yağ asitlerinin amino asitlere çevrilerek proteinleşmesi', 'Fosfat grubunun eklenmesi'], 'Hidrojenleme, doymamış yağ asitlerindeki çift bağlara hidrojen ekleyerek onları doymuş hâle getirir; bu da erime noktasını yükseltir.'),
  ('Uzun süre aç kalan bir kişide vücut proteinleri enerji amacıyla kullanılmaya başlarsa kanda hangi atık maddenin artması beklenir?', 'Üre', ['Karbon monoksit', 'Glikojen', 'Nişasta'], 'Amino asitler yıkılırken amino grupları amonyağa, karaciğerde de üreye dönüştürülür. Bu yüzden protein yıkımı üre üretimini artırır.'),
  ('Dört polipeptit zincirinden oluşan bir protein toplam 600 amino asit içeriyor. Bu proteinin sentezinde toplam kaç molekül su açığa çıkmıştır?', '596', ['599', '600', '604'], 'Her zincirde (amino asit sayısı − 1) bağ vardır. Dört zincir için toplam 600 − 4 = 596 peptit bağı ve aynı sayıda su oluşur.'),
  ('Bazı küçük proteinler hafif denatüre edildikten sonra uygun ortama alındığında yeniden işlevsel biçimlerini kazanabilmektedir. Bu gözlem en çok hangi sonucu destekler?', 'Proteinin üç boyutlu biçimini amino asit dizisi belirler.', ['Proteinlerin biçimi rastgele oluşur.', 'Denatürasyonda bütün peptit bağları kopar ve onarılamaz.', 'Proteinin işlevi biçiminden bağımsızdır.'], 'Ribonükleaz deneyleri, yalnız amino asit dizisi korunduğunda proteinin doğru katlanabildiğini göstermiştir; yani dizi biçimi belirler.'),
  ('İki farklı amino asitten (A ve B) birer tane kullanılarak oluşturulabilecek farklı dipeptit sayısı kaçtır?', '2', ['1', '3', '4'], 'Dipeptitte zincirin bir amino ucu ve bir karboksil ucu vardır; bu nedenle A−B ve B−A birbirinden farklıdır ve iki dipeptit elde edilir.'),
  ('Protein yapısında aşağıdakilerden hangisi kovalent bir bağdır?', 'İki sistein arasındaki disülfit köprüsü', ['Yan zincirler arasındaki hidrojen bağı', 'Zıt yüklü yan zincirler arasındaki iyonik etkileşim', 'Apolar yan zincirlerin hidrofobik etkileşimi'], 'Disülfit köprüsü iki kükürt atomu arasında kurulan kovalent bir bağdır ve üçüncül yapıyı özellikle sağlamlaştırır.'),
  ('Yarışmalı ve yarışmasız inhibitörleri ayırt etmek için yapılan bir deneyde substrat derişimi çok artırılıyor ve tepkime hızı neredeyse normale dönüyor. Ortamdaki inhibitör için en olası çıkarım hangisidir?', 'Yarışmalı inhibitördür.', ['Yarışmasız inhibitördür.', 'Enzimi kalıcı olarak denatüre etmiştir.', 'Koenzim olarak görev yapmaktadır.'], 'Bol substrat, aktif bölge için yarışan inhibitörü yerinden eder; bu yalnız yarışmalı inhibisyonda görülür. Yarışmasız inhibitör başka bölgeye bağlandığından etkisi sürer.'),
  ('Beslenmesinde yalnız kabuğu soyulmuş pirinç bulunan topluluklarda görülen beriberi hastalığı hangi vitaminin eksikliğiyle ilişkilidir?', 'B₁ (tiamin)', ['B₁₂ (kobalamin)', 'C (askorbik asit)', 'D (kalsiferol)'], 'Pirinç kabuğu tiamin bakımından zengindir. Kabuğu soyulmuş pirinçle beslenme B₁ eksikliğine ve sinir sistemi bozukluklarına yol açar.'),
  ('Aynı uzunluktaki iki çift zincirli DNA molekülünden birinde G–C baz çiftlerinin oranı daha yüksektir. Bu molekül için hangisi beklenir?', 'Zincirlerini birbirinden ayırmak için daha yüksek sıcaklık gerekir.', ['Molekülde daha az hidrojen bağı bulunur ve zincirleri düşük sıcaklıkta kolayca ayrılır.', 'Molekülde adenin miktarı timinden fazladır.', 'Molekül yapısında riboz şekeri taşır.'], 'G–C çiftleri üç hidrojen bağıyla bağlandığından G–C oranı yüksek DNA\'nın iplikleri daha zor ayrılır ve erime sıcaklığı yükselir.'),
  ('Çift zincirli DNA\'da pürin bazlarının sayısı için hangisi her zaman doğrudur?', 'Pirimidin bazlarının sayısına eşittir.', ['Pirimidin bazlarının sayısının iki katıdır.', 'Timin sayısına eşittir.', 'Toplam baz sayısının dörtte biridir.'], 'Her baz çiftinde bir pürin bir pirimidinle eşleşir (A–T, G–C); bu yüzden toplam pürin sayısı toplam pirimidin sayısına eşittir.'),
  ('Bir virüsün nükleik asidinde adenin %25, urasil %25, guanin %30 ve sitozin %20 bulunuyor. Bu nükleik asit için en doğru çıkarım hangisidir?', 'Tek zincirli bir RNA\'dır.', ['Çift zincirli bir DNA\'dır.', 'Tek zincirli bir DNA\'dır.', 'Çift zincirli bir RNA\'dır.'], 'Urasil bulunması molekülün RNA olduğunu gösterir. G ve C oranlarının eşit olmaması da baz eşleşmesi yapan ikinci bir zincir olmadığını, yani tek zincirli olduğunu gösterir.'),
  ('Hücre çekirdeğini bitki hücrelerinde tanımlayıp ona "nucleus" adını veren bilim insanı kimdir?', 'Robert Brown', ['Robert Hooke', 'Louis Pasteur', 'Matthias Schleiden'], 'İskoç botanikçi Robert Brown 1831\'de orkide hücrelerinde çekirdeği tanımlamıştır.'),
  ('Pasteur\'ün kuğu boyunlu şişe deneyi hücre teorisinin hangi ilkesini destekler?', 'Canlıların yalnız önceden var olan canlılardan oluşması', ['Bütün hücrelerin çekirdek taşıması', 'Hücrelerin enerji üretmemesi', 'Bitki ve hayvan hücrelerinin aynı yapıda olması ve aynı organelleri taşıması'], 'Pasteur, dış ortamdan mikrop girmeyen kaynatılmış besin suyunda canlı oluşmadığını göstererek kendiliğinden oluş görüşünü çürüttü.'),
  ('Kenarı 1 birim olan küp biçimli bir hücrenin kenarı 3 birime çıkarsa yüzey alanının hacme oranı nasıl değişir?', 'Üçte birine düşer.', ['Üç katına çıkar.', 'Dokuz katına çıkar.', 'Değişmez.'], 'Kenar 1 iken oran 6/1 = 6; kenar 3 iken yüzey 54, hacim 27 olur ve oran 2\'ye iner. 2/6 = 1/3.'),
  ('Penisilinin bakterileri öldürürken insan hücrelerine aynı şekilde zarar vermemesinin nedeni nedir?', 'Bakteri hücre duvarı sentezini hedef alması, insan hücrelerinde ise hücre duvarı bulunmaması', ['İnsan hücrelerinde ribozom bulunmaması ve bu yüzden protein sentezinin olmaması', 'Bakterilerin zarla çevrili çekirdeğini parçalayarak DNA\'larını yok etmesi', 'İnsan hücre zarının penisilini enerji kaynağı olarak kullanması'], 'Penisilin peptidoglikan duvarın kurulmasını engeller. Hayvan hücrelerinde hücre duvarı olmadığından bu hedef bulunmaz.'),
  ('Memelilerin olgun alyuvarlarının çekirdek ve mitokondri taşımaması bu hücrelerle ilgili hangi sonucu doğurur?', 'Bölünemez ve enerjilerini oksijensiz yolla elde ederler.', ['Bol miktarda oksijen tüketip hızla bölünürler.', 'Kendi hemoglobinlerini çekirdeklerindeki genlerle sürekli yeniden sentezlerler.', 'Oksijeni mitokondride depolayarak taşırlar.'], 'Çekirdeği olmayan hücre bölünemez ve yeni protein üretemez. Mitokondri yokluğunda ATP yalnız glikoliz ve fermantasyonla elde edilir; böylece taşıdıkları oksijeni kendileri tüketmezler.'),
  ('Hayvan hücre zarında bulunan kolesterolün zar üzerindeki etkisi hangisidir?', 'Zarın akışkanlığını sıcaklık değişimlerine karşı dengelemek', ['Zarı tamamen katılaştırıp madde geçişini durdurmak', 'Zarda enerji üretip hücreye ATP sağlamak', 'Zara selüloz lifleri ekleyerek hücre duvarına dönüştürmek'], 'Kolesterol yüksek sıcaklıkta fosfolipit hareketini kısıtlar, düşük sıcaklıkta ise sıkı paketlenmeyi önler; böylece zar akışkanlığını dengeler.'),
  ('İnsan ve fare hücreleri kaynaştırıldığında, iki türe ait zar proteinlerinin kısa sürede zarın her yerine karıştığı görülmüştür. Bu deney zarın hangi özelliğini doğrudan destekler?', 'Zar bileşenlerinin yanal olarak hareket edebilmesi', ['Zarın yalnız proteinlerden oluşması', 'Zar proteinlerinin türe özgü olmaması', 'Zarın tamamen katı ve sabit olması'], 'Bu deney, proteinlerin lipit katmanı içinde serbestçe kayabildiğini göstererek akıcı mozaik modeli desteklemiştir.'),
  ('Kolaylaştırılmış difüzyonda dış ortamdaki madde derişimi sürekli artırılırken taşıma hızının bir noktadan sonra artmaması nasıl açıklanır?', 'Taşıyıcı proteinlerin tamamının dolu olması', ['Hücrenin ATP\'sinin tükenmesi', 'Zarın fosfolipitlerinin parçalanması', 'Maddenin hücre içinde ürüne dönüşmesi ve geri çıkması'], 'Taşıyıcı proteinlerin sayısı sınırlıdır; hepsi meşgul olduğunda taşıma hızı en üst düzeyde sabitlenir. Bu durum basit difüzyonda görülmez.'),
  ('Tatlı sularda yaşayan tek hücreli paramesyumda kontraktil (vurgan) koful bulunurken deniz suyunda yaşayan pek çok tek hücrelide bu yapının bulunmaması nasıl açıklanır?', 'Tatlı su hipotonik olduğundan hücreye sürekli giren fazla suyun dışarı atılması gerekir.', ['Deniz suyu hipotonik olduğundan hücreye hiç su girmez.', 'Tatlı suda tuz derişimi hücre içinden fazladır.', 'Deniz suyunda yaşayan tek hücrelilerde hücre zarı bulunmaz.'], 'Tatlı su hücre içine göre hipotoniktir; osmozla giren su kontraktil kofulla dışarı pompalanır. Deniz suyu hücreyle yaklaşık izotonik olduğundan böyle bir yapıya gerek kalmaz.'),
  ('Bağırsak hücrelerinde glikozun, sodyum iyonlarının derişim farkı yönündeki akışıyla birlikte hücreye derişim farkına karşı alınması hangi taşıma biçimine örnektir?', 'İkincil aktif taşıma', ['Basit difüzyon', 'Fagositoz', 'Osmoz ve ardından gelen plazmoliz'], 'Na⁺-K⁺ pompasının oluşturduğu sodyum farkı bir enerji kaynağı gibi kullanılır; glikoz sodyumla aynı taşıyıcıdan girer. ATP dolaylı olarak harcandığı için ikincil aktif taşıma denir.'),
  ('Ekzositoz sırasında kesecik zarı hücre zarıyla kaynaştığı için hücre zarında hangi değişiklik olur?', 'Hücre zarının yüzey alanı artar.', ['Hücre zarının yüzey alanı azalır.', 'Hücre zarı tamamen geçirimsiz olur.', 'Hücre zarından fosfolipitler çıkarılır ve zar incelir.'], 'Kesecik zarı hücre zarına eklenir; bu nedenle ekzositoz zar yüzeyini genişletirken endositoz zar yüzeyini azaltır.'),
  ('Kolesterol taşıyan LDL parçacıklarının hücre zarındaki özel reseptörlere bağlandıktan sonra keseciklerle hücreye alınması hangi olaya örnektir?', 'Reseptör aracılı endositoz', ['Basit difüzyon', 'Sodyum-potasyum pompası', 'Ekzositoz ve salgılama'], 'Bu süreçte hücre yalnız reseptörüne bağlanan belirli molekülleri seçerek içeri alır; böylece düşük derişimdeki maddeler bile verimli biçimde toplanır.'),
  ('Protein sentezinin çok yoğun olduğu hücrelerde çekirdekçiğin genellikle büyük ve belirgin olması nasıl açıklanır?', 'Bu hücrelerin çok sayıda ribozoma ihtiyaç duyması', ['Çekirdekçiğin sentezlenen proteinlerin depolandığı yer olması', 'Çekirdekçiğin ATP ürettiği organel olması', 'Bu hücrelerde DNA miktarının sürekli azalması'], 'Ribozom alt birimleri çekirdekçikte üretildiği için yoğun protein sentezleyen hücrelerde çekirdekçik büyür.'),
  ('Asetabularya adlı tek hücreli algin iki türü arasında yapılan çekirdek nakli deneylerinde, yeniden oluşan şapkanın biçimi neye göre belirlenmiştir?', 'Hücrede bulunan çekirdeğin ait olduğu türe göre', ['Hücrenin sitoplazmasının ve sapının ait olduğu türe göre', 'Hücrenin ortamdaki ışık miktarına göre', 'Alg hücresinin eski şapkasının biçimine göre'], 'Hämmerling\'in deneylerinde şapka biçimi sonunda çekirdeği veren türe benzedi; bu da kalıtsal bilginin çekirdekte olduğunu gösterdi.'),
  ('İskelet kası hücrelerinin çok çekirdekli olmasının nedeni nedir?', 'Gelişim sırasında birçok öncül hücrenin birleşmesi', ['Bu hücrelerin hiç bölünmemesi', 'Çekirdeğin enerji depolaması', 'Her çekirdeğin ayrı bir organel üretmesi ve onu yönetmesi'], 'İskelet kası lifleri, embriyonik miyoblastların kaynaşmasıyla oluşan uzun ve çok çekirdekli hücrelerdir.'),
  ('Kromatinin yoğun paketlenmiş (heterokromatin) ve gevşek (ökromatin) bölgeleri karşılaştırıldığında hangisi doğrudur?', 'Ökromatin bölgelerindeki genler genellikle daha etkin biçimde okunur.', ['Heterokromatin bölgelerinde gen okunması hücrenin en yüksek düzeyine ulaşır.', 'Ökromatin yalnız bölünme sırasında görülür.', 'Heterokromatin bölgelerinde DNA bulunmaz.'], 'Gevşek ökromatin, enzimlerin DNA\'ya ulaşmasını kolaylaştırır; sıkı paketlenmiş heterokromatin bölgeleri ise genellikle sessizdir.'),
  ('Bir hücrede serbest ribozomlarda sentezlenen proteinler ile granüllü ER üzerindeki ribozomlarda sentezlenen proteinler karşılaştırıldığında genel eğilim hangisidir?', 'Serbest ribozomlar daha çok hücre içinde kullanılacak proteinleri üretir.', ['Serbest ribozomlar yalnız salgı proteinlerini üretir.', 'ER\'deki ribozomlar yalnız sitoplazmada kalacak enzimleri üretip hiç salgı yapmaz.', 'İki ribozom grubunun yapıları tamamen farklıdır.'], 'Sitoplazmada kalan proteinler genellikle serbest ribozomlarda, salgılanacak ya da zara yerleşecek proteinler ise granüllü ER ribozomlarında üretilir. İki ribozom türü yapıca aynıdır.'),
  ('Mitokondri ve kloroplastın içinde bulunan ribozomların prokaryot ribozomlarına benzemesi en çok hangi görüşü destekler?', 'Bu organellerin geçmişte hücre içine alınmış bakterilerden kökenlendiği görüşünü', ['Bu organellerin hücre zarından oluştuğu görüşünü', 'Bakterilerin ökaryot hücrelerin organellerinden türediğini öne süren görüşü', 'Ribozomların yalnız çekirdekte üretildiği görüşünü'], 'Endosimbiyoz kuramına göre mitokondri ve kloroplast, ataları serbest yaşayan prokaryotlardır; kendi DNA\'ları ve 70S ribozomları bu kökeni destekler.'),
  ('Kas hücrelerinde özelleşmiş düz endoplazmik retikulum olan sarkoplazmik retikulumun görevi nedir?', 'Kasılma için gerekli kalsiyum iyonlarını depolayıp salmak', ['Kasın glikojenini nişastaya dönüştürüp uzun süreli depolamak', 'Kas proteinlerini lizozom gibi sindirmek', 'Kas hücresine oksijen taşıyıp depolamak'], 'Sinir uyarısı geldiğinde sarkoplazmik retikulum depoladığı Ca²⁺ iyonlarını sitoplazmaya bırakır ve kasılma başlar.'),
  ('Radyoaktif işaretli amino asitler verilen bir pankreas hücresinde radyoaktivitenin zaman içinde önce granüllü ER\'de, sonra Golgi\'de, en son salgı keseciklerinde görülmesi hangi sonucu destekler?', 'Salgı proteinlerinin bu organeller arasında sırayla taşındığını', ['Golgi cisimciğinin hücrede protein sentezlenen tek yer olduğunu', 'Amino asitlerin doğrudan hücre dışına çıktığını', 'Salgı keseciklerinin ribozom ürettiğini'], 'Bu "nabız-kovalama" deneyleri salgı yolunun ER\'den Golgi\'ye, oradan keseciklere doğru ilerlediğini göstermiştir.'),
  ('Lizozom enzimlerinin asidik ortamda çalışması, bir lizozomun patlaması durumunda hücreye verilecek zararı nasıl etkiler?', 'Sitoplazma nötre yakın olduğu için sızan enzimlerin etkisi sınırlı kalır.', ['Sitoplazmada enzimler daha hızlı çalışarak hücreyi saniyeler içinde eritir.', 'Sızan enzimler sitoplazmada ATP\'ye dönüşür.', 'Sızan enzimler çekirdek zarına yapışarak onu güçlendirir.'], 'Sitoplazmanın pH\'ı yaklaşık 7,2\'dir; bu ortamda lizozom enzimlerinin etkinliği düşer. Bu durum hücreyi kendi enzimlerine karşı korur.'),
  ('Lizozomal enzimlerden birinin eksik olduğu kalıtsal depo hastalıklarında hücrede ne gözlenmesi beklenir?', 'Sindirilemeyen maddelerin lizozomlarda birikmesi', ['Lizozom sayısının tamamen sıfırlanması ve hücrenin bölünmesi', 'Hücrenin fotosentez yapmaya başlaması', 'Mitokondrilerin lizozoma dönüşmesi'], 'Belirli bir hidrolaz yoksa onun substratı parçalanamaz ve lizozomlarda birikerek hücre işlevini bozar; Tay-Sachs hastalığı buna örnektir.'),
  ('İnsanda mitokondrilerin genellikle yalnız anneden kalıtılmasının nedeni nedir?', 'Döllenmede zigotun sitoplazmasının büyük ölçüde yumurtadan gelmesi', ['Sperm hücrelerinde hiç DNA bulunmaması ve çekirdeğin yumurtadan gelmesi', 'Babanın mitokondrilerinin çekirdeğe yerleşmesi', 'Yumurtanın çekirdeğinde mitokondri üretilmesi'], 'Zigotun sitoplazması ve organelleri yumurtadan gelir; spermin az sayıdaki mitokondrisi genellikle zigota katılmaz ya da yıkılır.'),
  ('Toprak altında bırakılan bir patates yumrusunun ışık gören yüzeyinin zamanla yeşillenmesi hangi olayla açıklanır?', 'Lökoplastların ışık etkisiyle kloroplasta dönüşmesi', ['Mitokondrilerin ışık görünce klorofil üretmeye başlaması', 'Kromoplastların koful hâline gelmesi', 'Nişastanın doğrudan klorofile dönüşmesi'], 'Plastitler birbirine dönüşebilir; ışık alan lökoplastlarda klorofil sentezlenir ve kloroplastlar gelişir.'),
  ('Sinir hücresinin uzun aksonu boyunca hücre gövdesinde üretilen keseciklerin akson ucuna taşınmasında hangi yapılar yol işlevi görür?', 'Mikrotübüller', ['Ribozomlar', 'Lizozomlar', 'Kofullar'], 'Motor proteinler kesecikleri mikrotübüller üzerinde "ray üzerinde tren" gibi taşır; aksonlarda bu taşıma çok belirgindir.'),
  ('Sentriyollerin yapısı için hangisi doğrudur?', 'Dokuz grup hâlinde dizilmiş üçlü mikrotübüllerden oluşur.', ['İki tabakalı zarla çevrili kesecikten oluşur.', 'Aktin ve miyozin liflerinin sarmalından oluşur.', 'Ortasında bir çift tek mikrotübül bulunan 9+2 düzenindedir.'], 'Sentriyoller "9×3" düzeninde, ortasında mikrotübül bulunmayan silindirik yapılardır. 9+2 düzeni ise sil ve kamçının eksenidir.'),
  ('Kartagener sendromu olan kişilerde sil ve kamçıdaki motor proteinler (dinein) bozuktur. Bu kişilerde aşağıdakilerden hangisinin görülmesi beklenir?', 'Sık solunum yolu enfeksiyonları ve sperm hareketsizliği', ['Kemiklerde aşırı kalsiyum birikmesi', 'Kanın pıhtılaşmasının hızlanması', 'Alyuvar sayısının iki katına çıkması ve kanın koyulaşması'], 'Dinein bozuk olunca solunum yolundaki siller mukusu temizleyemez ve sperm kamçısı hareket edemez; bu yüzden enfeksiyonlar ve kısırlık görülür.'),
  ('Odunsu bitkilerin ikincil hücre duvarında birikerek duvarı sertleştiren ve su geçirmez kılan madde hangisidir?', 'Lignin', ['Nişasta', 'Albümin', 'Kolesterol'], 'Lignin ikincil çeperde selüloz liflerinin arasına yerleşir; odun dokusunun sağlamlığı büyük ölçüde lignine bağlıdır.'),
  ('Hayvan hücreleri arasında bulunan ve komşu hücrelerin sitoplazmaları arasında iyon ile küçük molekül geçişine izin veren kanallar hangisidir?', 'Aralıklı bağlantılar', ['Sıkı bağlantılar', 'Desmozomlar', 'Hücre duvarındaki porlar ve plazmodezmalar'], 'Aralıklı bağlantılar kalp kasında iyon akışını sağlayarak hücrelerin eş zamanlı kasılmasına yardım eder. Sıkı bağlantılar ise hücreler arası sızıntıyı önler.'),
  ('Glikolizin başlangıcında glikozun ATP harcanarak fosforlanmasının hücreye sağladığı yarar nedir?', 'Glikozu etkinleştirip hücre dışına çıkmasını engellemek', ['Glikozu doğrudan karbondioksite dönüştürmek', 'Glikozun oksijenle tepkimeye girmesini önleyip hücreyi korumak', 'Hücrede ATP stokunu artırmak'], 'Fosforlanan glikoz kararsızlaşarak yıkıma hazır hâle gelir; yükü nedeniyle de zardaki glikoz taşıyıcılarından dışarı çıkamaz.'),
  ('Bir glikoz molekülünün oksijenli solunumla tamamen yıkılmasında açığa çıkan altı CO₂ molekülünün kaynağı hangi aşamalardır?', 'Pirüvatın asetil-KoA\'ya dönüşümü ve Krebs döngüsü', ['Yalnız glikoliz', 'Yalnız elektron taşıma sistemi', 'Glikoliz ile elektron taşıma sisteminin son basamakları birlikte'], 'İki pirüvattan asetil-KoA oluşurken 2 CO₂, iki Krebs döngüsünde 4 CO₂ çıkar. Glikoliz ve ETS\'de CO₂ oluşmaz.'),
  ('Mitokondride ATP sentaz enziminin çalışmasını sağlayan doğrudan enerji kaynağı hangisidir?', 'İç zarın iki yanındaki H⁺ (proton) derişim farkı', ['Glikozun doğrudan bu enzime bağlanması', 'Matriksteki oksijen derişiminin azalması', 'Dış zardaki porlardan matrikse giren ışık enerjisi'], 'ETS, protonları zarlar arası boşluğa pompalar. Protonlar ATP sentazdan geri akarken açığa çıkan enerjiyle ADP\'den ATP sentezlenir (kemiozmoz).'),
  ('Mitokondri iç zarının protonlara karşı geçirgen hâle getirildiği bir deneyde ETS\'nin oksijen tüketmeye devam ettiği hâlde ATP üretiminin büyük ölçüde düştüğü gözleniyor. Bu sonucun nedeni nedir?', 'Proton farkı oluşamadığı için ATP sentazın çalışamaması', ['Oksijenin Krebs döngüsünü durdurması', 'Glikolizin tamamen hızlanıp hiç pirüvat üretmemesi ve Krebsin durması', 'ETS proteinlerinin hücre zarına taşınması'], 'Elektron akışı sürse de protonlar zardan geri sızdığında kemiozmotik fark kurulamaz; enerji ATP yerine ısı olarak açığa çıkar.'),
  ('Oksijenli solunumda üretilen suyun oksijen atomları nereden gelir?', 'Solunumda kullanılan moleküler oksijenden', ['Glikozun yapısındaki oksijenden', 'Karbondioksitin oksijeninden', 'Hücrenin dışarıdan aldığı sudaki oksijen atomlarından'], 'ETS sonunda O₂, elektron ve protonlarla birleşerek su oluşturur; bu nedenle suyun oksijeni soluduğumuz oksijenden gelir.'),
  ('Fermantasyonda pirüvatın laktik asit ya da etil alkole dönüştürülmesinin hücre için asıl önemi nedir?', 'Glikolizin sürmesi için gerekli NAD⁺\'nın yeniden oluşturulması', ['Bu basamakta çok sayıda ATP üretilmesi', 'Karbondioksitin hücrede depolanması', 'Oksijen üretilerek elektron taşıma sisteminin yeniden başlatılması'], 'Fermantasyonun son basamağında ATP üretilmez; NADH yükseltgenerek NAD⁺ geri kazanılır. NAD⁺ olmadan glikoliz durur.'),
  ('Bir kapta glikoz çözeltisindeki maya hücrelerine oksijen verilmesi durdurulduğunda glikoz tüketim hızının arttığı gözleniyor. Bunun en olası nedeni nedir?', 'Fermantasyonda glikoz başına az ATP elde edildiğinden aynı enerji için daha çok glikoz yıkılması', ['Oksijensiz ortamda mayaların klorofil üretip fotosenteze başlaması ve glikoz harcaması', 'Mayaların oksijen yokluğunda glikozu depolaması', 'Oksijenin glikozu kendiliğinden yakması'], 'Oksijensiz ortamda maya glikoz başına yalnız 2 ATP kazanır; enerji gereksinimini karşılamak için glikozu çok daha hızlı tüketir (Pasteur etkisi).'),
  ('Engelmann, bir ipliksi alge prizmadan geçirilmiş ışık düşürüp oksijen seven bakterilerin dağılımını incelemiştir. Bakterilerin hangi bölgelerde toplandığı gözlenmiştir?', 'Mavi ve kırmızı ışık düşen bölgelerde', ['Yalnız yeşil ışık düşen bölgelerde', 'Yalnız sarı ışık düşen bölgelerde', 'Alg boyunca ışığın her renginde eşit sayıda ve dağınık'], 'Bakteriler oksijenin en çok üretildiği yerlerde toplanmıştır; bu bölgeler klorofilin en iyi soğurduğu mavi ve kırmızı ışık bölgeleridir.'),
  ('Işık tepkimelerinde ATP üretimi mitokondridekine benzer biçimde hangi mekanizmayla gerçekleşir?', 'Tilakoit zarının iki yanında oluşan proton farkının ATP sentazı çalıştırması', ['Glikozun tilakoit içinde fosforlanması', 'Karbondioksitin doğrudan ATP\'ye dönüşmesi', 'Oksijenin ATP sentaza bağlanması ve ADP\'yi doğrudan fosforlayarak ATP üretmesi'], 'Elektron taşınması sırasında protonlar tilakoit boşluğunda birikir; ATP sentazdan stromaya geri dönerken ATP üretilir. Buna fotofosforilasyon denir.'),
  ('Nitrifikasyon bakterileri kemosentez için hangi tepkimelerden enerji sağlar?', 'Amonyağın nitrite ve nitritin nitrata yükseltgenmesi', ['Nitratın azot gazına indirgenmesi', 'Glikozun maya hücrelerinde etil alkole dönüşmesi', 'Suyun ışık etkisiyle parçalanması'], 'Nitrosomonas amonyağı nitrite, Nitrobacter nitriti nitrata yükseltger; açığa çıkan enerji kemosentezde kullanılır.'),
  ('Karotenoit pigmentlerinin fotosentezdeki işlevleri arasında hangisi yer alır?', 'Klorofilin soğuramadığı dalga boylarını soğurup enerjiyi klorofile aktarmak', ['Karbondioksiti stromada bağlayarak Kalvin döngüsünü ışık olmadan başlatmak', 'Glikozu nişastaya dönüştürmek', 'Oksijeni tilakoitten dışarı pompalamak'], 'Karotenoitler yardımcı pigmentlerdir; mavi-yeşil ışığı soğurup enerjiyi klorofile aktarır ve klorofili aşırı ışığın zararından korur.'),
  ('Kolşisin, iğ ipliklerini oluşturan mikrotübüllerin kurulmasını engeller. Kolşisin uygulanan bölünen hücreler hangi evrede birikir?', 'Metafaz', ['G₁', 'S', 'Telofaz'], 'İğ iplikleri olmadan kromozomlar kutuplara çekilemez ve hücreler metafazda takılı kalır; bu yöntem karyotip hazırlamada kullanılır.'),
  ('Kromozom sayısı 2n = 46 olan bir insan hücresi mitoz anafaz evresindeyken hücrede toplam kaç kromozom bulunur?', '92', ['23', '46', '184'], 'Anafazda kardeş kromatitler ayrılınca her biri bağımsız kromozom sayılır; hücrede geçici olarak 2 × 46 = 92 kromozom bulunur.'),
  ('Bir kök ucu preparatında 200 hücre sayılıyor ve bunların 180\'inin interfazda, 20\'sinin mitozun çeşitli evrelerinde olduğu görülüyor. Hücre döngüsü 20 saat sürüyorsa mitozun yaklaşık süresi kaç saattir?', '2', ['1', '4', '18'], 'Bir evredeki hücre oranı o evrenin süresiyle orantılıdır. Mitoz oranı 20/200 = 0,1; 0,1 × 20 saat = 2 saat.'),
  ('Bir hücrede çekirdek zarı parçalanmış, kromozomlar yoğunlaşmış ancak henüz ekvatorda dizilmemiştir. Bu hücre hangi evrededir?', 'Profazın sonu', ['Anafazın başlangıcı', 'Telofazın sonu', 'G₂ evresinin son kısmı'], 'Çekirdek zarının parçalanması profaz sonunda olur; iğ iplikleri kromozomlara bağlanıp onları ekvatora taşıdığında metafaza geçilir.'),
  ('Çekirdek bölünmesi gerçekleştiği hâlde sitokinezin gerçekleşmediği bir hücrede ne gözlenir?', 'Çok çekirdekli tek bir hücre oluşur.', ['Kromozom sayısı yarıya iner.', 'İki ayrı tek çekirdekli hücre oluşur.', 'Hücre hemen ölür ve parçalanır.'], 'Karyokinez tamamlanıp sitokinez olmazsa çekirdekler ayrılır ama sitoplazma bölünmez; sonuçta çok çekirdekli bir hücre meydana gelir.'),
  ('G₂ kontrol noktasının temel görevi nedir?', 'DNA eşlenmesinin eksiksiz ve hatasız tamamlandığını denetlemek', ['Hücrenin yeterince büyüyüp büyümediğini ilk kez denetlemek', 'Kromozomların iğ ipliklerine bağlandığını denetlemek', 'Sitokinezi başlatmak'], 'G₂/M kontrol noktası, DNA\'nın tam ve hasarsız eşlendiğinden emin olmadan hücrenin mitoza girmesini engeller.'),
  ('Normalde hücre bölünmesini uyaran, ancak mutasyona uğradığında sürekli etkin kalarak kansere yol açabilen genlere ne ad verilir?', 'Onkogenler', ['Tümör baskılayıcı genler', 'Histon genleri', 'Ribozomal genler'], 'Proto-onkogenler bölünmeyi düzenler; mutasyonla onkogene dönüştüğünde "gaz pedalı sıkışmış" gibi bölünmeyi sürekli uyarır.'),
  ('p53 gibi tümör baskılayıcı genlerin görevi nedir?', 'Hasarlı DNA\'yı onartmak ya da onarılamazsa hücre bölünmesini durdurmak', ['Hücre bölünmesini her koşulda hızlandırıp hücreleri sürekli çoğalmaya zorlamak', 'Kromozom sayısını artırmak', 'Hücreye sürekli besin taşımak'], 'Tümör baskılayıcı genler döngünün frenleridir; hasar onarılamazsa hücreyi apoptoza yönlendirerek kanser oluşumunu engeller.'),
  ('Mayoz I\'de kromozom sayısının yarıya inmesinin nedeni hangisidir?', 'Homolog kromozomların birbirinden ayrılarak farklı hücrelere gitmesi', ['Kardeş kromatitlerin interfazda birbirinden ayrılarak farklı hücrelere gitmesi', 'DNA\'nın eşlenmemesi', 'Sitoplazmanın bölünmemesi'], 'Anafaz I\'de homolog kromozomlar ayrılıp zıt kutuplara çekilir; her yavru hücreye her çiftten yalnız bir kromozom düşer, böylece sayı yarıya iner.'),
  ('2n = 6 kromozomlu bir hücrede homolog kromozomların bağımsız dağılımı sonucu oluşabilecek farklı gamet çeşidi sayısı (krossing over hariç) kaçtır?', '8', ['3', '6', '16'], 'Haploit kromozom sayısı n = 3 olduğundan gamet çeşidi 2ⁿ = 2³ = 8 ile hesaplanır.'),
  ('Mayoz sırasında homolog kromozomların ya da kardeş kromatitlerin ayrılmaması (ayrılmama) olayının gametlere etkisi nedir?', 'Bazı gametlerin fazla, bazılarının eksik kromozom taşıması', ['Bütün gametlerin kromozom sayısının iki katına çıkması', 'Gamet oluşumunun hızlanması', 'Krossing over oranının artması'], 'Ayrılmama (non-disjunction) sonucunda bir gamet fazladan kromozom alırken diğeri eksik kalır; bu durum kromozom sayısı bozukluklarına yol açabilir.'),
  ('Down sendromunun 21. kromozomdan üç tane bulunmasıyla ortaya çıkması, mayozla ilgili hangi olayın sonucudur?', 'Kromozomların ayrılmaması', ['Krossing over', 'Normal bağımsız dağılım', 'DNA\'nın iki kez eşlenmesi'], 'Mayozda 21. kromozom çiftinin ayrılmaması, fazladan bir 21. kromozom taşıyan gamet oluşturur; döllenmeyle birey bu kromozomdan üç tane taşır (trizomi 21).'),
  ('Eşeysiz üremenin, çevre koşulları aniden değiştiğinde dezavantaj oluşturmasının nedeni nedir?', 'Bireyler arasında kalıtsal çeşitlilik bulunmaması', ['Üremenin çok yavaş olması', 'Her bireyin farklı genlere sahip olması', 'Bireylerin hiç bölünememesi'], 'Kalıtsal olarak aynı bireyler aynı çevresel baskıya aynı biçimde tepki verir; yeni bir hastalık ya da koşul tüm topluluğu birden etkileyebilir.'),
  ('Hücre farklılaşması sırasında bir hücrenin özelleşmesini en iyi açıklayan ifade hangisidir?', 'Hücredeki genlerin bir kısmının etkinleşip bir kısmının susturulması', ['Hücrenin özelleşme sırasında bazı genlerini tümüyle kaybederek atması', 'Hücrenin kromozom sayısının artması', 'Hücrenin DNA\'sının yarıya inmesi'], 'Farklılaşan hücreler aynı DNA\'yı taşır; hangi genlerin okunacağı değiştiği için hücreler farklı yapı ve işlev kazanır.'),
  ('Steroit hormonların hücre içindeki reseptörlere doğrudan bağlanabilmesinin nedeni nedir?', 'Yağda çözünerek hücre zarından kolayca geçebilmeleri', ['Çok büyük moleküller oldukları için zar porlarından güçlükle geçebilmeleri', 'Suda çok iyi çözünmeleri', 'Protein yapıda olmaları'], 'Steroitler apolar olduğundan lipit zardan geçer ve sitoplazma ya da çekirdekteki reseptörlerine bağlanarak gen ifadesini etkiler.'),
  ('Bir organizmada yaşlanan ve işlevini yitiren hücrelerin yerine yenilerinin gelmesi için hangi iki olayın dengede olması gerekir?', 'Hücre bölünmesi ve programlı hücre ölümü', ['Fotosentez ile oksijenli solunumun hücrede birbirini dengelemesi olayları', 'Difüzyon ve osmoz', 'Sindirim ve boşaltım'], 'Doku dengesi, mitozla yeni hücre üretimi ile apoptozla eski hücrelerin temizlenmesi arasındaki dengeye bağlıdır.'),
  ('Hücredeki su, moleküllere bağlı olup olmamasına göre serbest ve bağlı su olarak ikiye ayrılır. Metabolik tepkimelere doğrudan katılabilen su hangisidir?', 'Serbest su', ['Bağlı su', 'Buz hâlindeki su', 'Kristal su'], 'Serbest su çözücü olarak iş görür ve tepkimelere katılır; bağlı su ise moleküllere tutunmuş olduğundan bu işlevleri yerine getiremez.'),
  ('Bir maddenin hücre içine girişi, dış derişimi belirli bir noktaya kadar artırıldığında doğrusal artarken sonra sabitleniyor; ayrıca solunum zehri bu girişi durdurmuyor. Bu madde hangi yolla taşınır?', 'Kolaylaştırılmış difüzyonla', ['Aktif taşımayla', 'Basit difüzyonla', 'Fagositozla'], 'Doygunluk göstermesi taşıyıcı protein kullanıldığını, solunum zehrinden etkilenmemesi ise ATP harcanmadığını gösterir; bu, kolaylaştırılmış difüzyondur.'),
  ('Bir yaprağın fotosentez ve solunumunun eşit hızda olduğu, dışarıya net oksijen verilmeyen ışık şiddetine ne ad verilir?', 'Telafi (dengeleme) noktası', ['Doygunluk noktası', 'Optimum sıcaklık', 'Solunum eşiği'], 'Telafi noktasında fotosentezle üretilen oksijen solunumda tüketilenle eşittir; hücre dışına net gaz alışverişi olmaz.'),
  ('Hücre solunumunda glikoz dışında yağların ve proteinlerin de yakıt olarak kullanılabilmesi nasıl açıklanır?', 'Yağ ve proteinlerin yıkım ürünlerinin solunum basamaklarına ara ürün olarak katılabilmesi', ['Yağ ve proteinlerin önce tümüyle glikoza dönüştürülüp ardından yavaşça yakılması gerekmesi', 'Bu moleküllerin yalnız fotosentezde kullanılması', 'Yağ ve proteinlerin enerji içermemesi'], 'Yağlar gliserol ve yağ asitlerine, proteinler amino asitlere yıkılır; bu ürünler glikoliz ve Krebs döngüsünün uygun basamaklarına katılarak enerji verir.'),
  ('Bir DNA molekülünün bir zincirinde bulunan baz dizisi 5\'-ATGC-3\' ise bu zincirle eşleşen karşı zincirin baz dizisi hangisidir?', '3\'-TACG-5\'', ['3\'-ATGC-5\'', '3\'-UACG-5\'', '3\'-TAGC-5\''], 'DNA\'da A ile T, G ile C eşleşir ve zincirler ters yöndedir. Verilen zincirin karşısına T, A, C, G gelir.'),
  ('Mitokondri ve kloroplastın kendi DNA\'ları ve ribozomları sayesinde yapabildikleri nedir?', 'Kendi proteinlerinin bir kısmını sentezleyip çoğalmaları', ['Fotosentez ve solunumu aynı anda durdurup hücreyi dinlenmeye almaları', 'Çekirdeğin görevini üstlenmeleri', 'Hücre zarını üretmeleri'], 'Bu organeller kendi DNA ve ribozomlarıyla bazı proteinlerini üretir ve ikiye bölünerek çoğalır; bu özellik endosimbiyoz kuramını destekler.'),
  ('Bir dokuda hücrelerin denetimden çıkıp kontrolsüz bölünmesi ile sağlıklı bir dokuda hücre bölünmesinin durması arasındaki fark neyle ilgilidir?', 'Hücre döngüsünün denetim mekanizmalarının çalışıp çalışmaması', ['Hücrelerin ribozom sayısı', 'Hücrelerin su oranı', 'Hücrelerin taşıdığı ribozom ve mitokondri sayısının birbirinden farklı olması'], 'Sağlıklı hücreler gerektiğinde bölünmeyi durdurur; denetim genleri bozulan hücreler durmadan bölünerek tümör oluşturur.'),
  ('Bir enzimin tepkime hızını, substrat bol olduğunda yalnız enzim miktarının sınırlaması hangi gözlemle anlaşılır?', 'Enzim miktarı artırıldığında hızın da artması', ['Substrat miktarı artırıldığında hızın sürekli artması', 'Sıcaklık düştüğünde hızın artması', 'pH değiştiğinde hızın değişmemesi'], 'Substrat fazlayken hızı belirleyen enzim sayısıdır; enzim eklenince boşta substrat olduğundan hız artar.'),
  ('Bir bitki hücresi tam turgor durumundayken su alımının durmasının nedeni nedir?', 'Hücre duvarının oluşturduğu turgor basıncının su girişini dengelemesi', ['Hücre zarının bir süre sonra suyu tamamen geçirmez duruma gelmesi ve kapanması', 'Hücrenin ATP üretmeyi bırakması', 'Kofulun tamamen boşalması'], 'Hücre su aldıkça artan turgor basıncı, suyu içeri çeken osmotik kuvveti dengeler; denge kurulunca net su girişi durur.'),
  ('Mitoz bölünme sonunda oluşan yavru hücrelerin kromozom sayısı ana hücreyle aynı olurken mayoz sonunda yarıya inmesinin nedeni nedir?', 'Mayozda art arda iki bölünme olup DNA\'nın yalnız bir kez eşlenmesi', ['Mayozda DNA hiç eşlenmeden art arda iki kez bölünme gerçekleşir.', 'Mitozda DNA\'nın iki kez eşlenmesi', 'Mayozda sitokinez olmaması'], 'Mayozda bir DNA eşlenmesinin ardından iki bölünme gerçekleşir; bu yüzden kromozom sayısı yarıya iner. Mitozda bir eşlenme ve bir bölünme olur, sayı korunur.'),
  ('Vücutta yaşlı ve hasarlı hücrelerin apoptozla temizlenmesi engellenirse hangi sorun ortaya çıkabilir?', 'Hasarlı hücrelerin birikip kontrolsüz çoğalması', ['Hücrelerin kromozom sayısının yarıya inmesi', 'Dokuların tamamen yok olması', 'Hücrelerin bölünmeyi bırakması'], 'Apoptoz baskılanırsa ölmesi gereken hasarlı hücreler yaşamaya ve bölünmeye devam eder; bu durum kanser gelişimine zemin hazırlayabilir.'),
  ('Kanın pH\'ını dengede tutan bikarbonat tamponu, kana asit eklendiğinde nasıl davranır?', 'Fazla H⁺ iyonlarını bağlayarak pH düşüşünü sınırlar.', ['Fazla H⁺ iyonlarını üretip pH\'ı daha da düşürür.', 'Kandaki suyu buharlaştırır.', 'Kanın tuz oranını artırır.'], 'Tampon sistemdeki bikarbonat, eklenen H⁺ iyonlarıyla birleşerek karbonik asit oluşturur ve pH\'ın belirgin düşmesini engeller.'),
  ('Bir monosakkaritin indirgen şeker olarak davranmasının anlamı nedir?', 'Benedict ya da Fehling çözeltisini indirgeyerek renk değiştirmesi', ['Suda hiçbir koşulda çözünmeyip yağ damlacıkları hâlinde kalması', 'Yalnız bitkilerde bulunması', 'Hidroliz edilerek amino aside ayrılması'], 'Glikoz ve fruktoz gibi indirgen şekerler serbest karbonil grubu taşır; bu grup Benedict çözeltisindeki bakırı indirgeyerek kiremit kırmızısı çökelti oluşturur.'),
  ('Hücre zarındaki taşıyıcı proteinlerin aktif taşımada enerji kullanması hangi gözlemle anlaşılır?', 'Solunumu durduran bir zehir uygulandığında taşımanın durması', ['Taşımanın derişim farkı yönünde ve hiçbir protein kullanılmadan gerçekleşmesi', 'Taşımanın hiçbir proteine gerek duymaması', 'Taşımanın yalnız gaz moleküllerinde görülmesi'], 'Aktif taşıma ATP\'ye bağımlıdır; solunum durup ATP üretimi kesilince derişim farkına karşı taşıma da durur.'),
  ('Bir hücreye radyoaktif işaretli amino asit verildiğinde radyoaktifliğin önce ribozomlarda, sonra Golgi\'de, en son salgı keseciklerinde görülmesi hangi süreci gösterir?', 'Protein sentezi ve salgılanma yolunu', ['DNA eşlenmesini', 'Fotosentez tepkimelerini', 'Hücre bölünmesini'], 'Amino asit önce ribozomda proteine katılır, ardından ER ve Golgi\'de işlenip keseciklerle salgılanır; radyoaktiflik bu yolu izler.'),
  ('Mitokondri iç zarında elektron taşıma sistemi çalışırken protonların biriktiği bölge neresidir?', 'İki zar arasındaki boşluk', ['Mitokondri matriksi', 'Sitoplazma', 'Çekirdek içi'], 'ETS proteinleri protonları matriksten iki zar arasındaki boşluğa pompalar; buradaki proton fazlalığı ATP sentezini yönlendirir.'),
  ('Bir dokuda hücrelerin %25\'inin mitozda olduğu gözleniyor. Bu dokudaki hücre döngüsünün süresi 16 saat ise mitoz yaklaşık kaç saat sürer?', '4', ['1', '8', '12'], 'Mitoz oranı 0,25; bu oran süreyle çarpılır: 0,25 × 16 = 4 saat.'),
  ('Kanser hücrelerinin tedavisinde kullanılan bazı ilaçların hızlı bölünen hücreleri hedef almasının yan etkisi nedir?', 'Saç kökü ve bağırsak gibi hızlı bölünen sağlıklı hücrelerin de zarar görmesi', ['Yalnız kanser hücrelerinin etkilenmesi', 'Kanser hücrelerinin daha hızlı bölünmeye başlaması', 'Hücrelerin kromozom sayısının artması'], 'Bu ilaçlar bölünen hücreleri hedef aldığından, hızlı bölünen normal hücreler (saç kökü, kemik iliği, bağırsak) de etkilenir ve saç dökülmesi gibi yan etkiler görülür.'),
  ('Steroit yapılı bir hormonun hücre içindeki reseptöre bağlandıktan sonra çoğunlukla hangi süreci etkilemesi beklenir?', 'Belirli genlerin ifadesini değiştirmesi', ['Hücre duvarını kalınlaştırması', 'Ribozomları parçalaması', 'Hücreyi hemen öldürmesi'], 'Steroit-reseptör kompleksi çekirdeğe giderek belirli genlerin okunmasını artırır ya da azaltır; böylece hücrenin protein üretimi değişir.'),
  ('Kemik iliği naklinin bazı kan hastalıklarının tedavisinde kullanılmasının temel nedeni nedir?', 'Kemik iliğindeki kök hücrelerin kan hücrelerini üretebilmesi', ['Kemik iliğinin oksijeni depolayıp gerektiğinde dokulara dağıtabilmesi özelliği', 'Kemik iliğinin antikor olması', 'Kemik iliğinin enzim salgılaması'], 'Kemik iliği, sürekli bölünerek kan hücrelerini üreten kök hücreler içerir; nakil, sağlıklı kan üretimini yeniden kurmayı amaçlar.'),
  ('Bir hücrenin yüzeyindeki glikoproteinlerin hücreler arası tanımada rol oynaması en çok hangi olayda önemlidir?', 'Doku ve organ nakillerinde uyum', ['Fotosentez hızının artması', 'ATP üretiminin hızlanması', 'Kromozom sayısının korunması'], 'Zar yüzeyindeki glikoproteinler hücrelerin "kimliğini" oluşturur; doku nakillerinde bu belirteçlerin uyumu reddedilmeyi belirler.'),
  ('Bir dokuda hücre bölünmesi ile programlı hücre ölümü dengede olmazsa ve ölüm engellenirse hangi sorun ortaya çıkabilir?', 'Hücrelerin aşırı birikmesi ve tümör oluşumu', ['Dokunun tamamen kaybolması ve hücrelerin sayıca hızla azalması', 'Hücre sayısının azalması', 'Kromozom sayısının artması'], 'Apoptoz baskılanıp bölünme devam ederse hücreler birikir; bu dengesizlik tümör oluşumuna zemin hazırlayabilir.'),
];
